# Source for q/ae-care4.js: Clinical care fourth batch (TEE/sedation, special patients, ICU, shock, ECG, labs, ethics/law).
C="Clinical care"
Q=[
# --- TEE and sedation ---
(C,"Common medicines used for moderate sedation during TEE include:","Midazolam and fentanyl",["Digoxin and warfarin","Insulin and heparin","Aspirin and statins"],"Propofol may be used by anesthesia staff for deeper sedation.","F"),
(C,"During TEE, the patient is usually positioned:","On the left side, with the head slightly bent forward",["Prone","Standing","On the right side with the neck extended"],"This helps saliva drain and eases probe insertion.","F"),
(C,"During TEE, which equipment must be ready at the bedside?","Suction, oxygen, monitoring and resuscitation equipment",["Only gel","A treadmill","An X-ray machine"],"Airway problems can occur with sedation.","F"),
(C,"Known esophageal varices or recent esophageal surgery are:","Relative or absolute contraindications to TEE that need specialist review",["No concern at all","A reason to use a larger probe","Only important for TTE"],"Benefits and risks are weighed by the physician.","F"),
(C,"Capnography during sedation monitors:","Exhaled carbon dioxide, giving early warning of slowed breathing",["Blood sugar","Heart rhythm","Blood pressure"],"It detects hypoventilation before oxygen saturation falls.","C"),
(C,"After TEE with throat anesthesia, the patient may start drinking when:","The gag reflex returns, often after about 1 hour, starting with small sips of water",["Immediately","After 24 hours","Never on the same day"],"This lowers the risk of aspiration.","F"),
(C,"A patient who received sedation for TEE should be discharged:","With an adult escort and told not to drive that day",["Alone, driving home","Immediately without checks","Only by ambulance"],"Sedation affects judgment and reaction time.","F"),
(C,"The ASA physical status classification is used to:","Describe a patient's overall health risk before sedation or anesthesia",["Grade valve disease","Measure EF","Score wall motion"],"ASA 1 is healthy; higher classes mean more illness.","C"),
# --- Special patients ---
(C,"A patient with severe shortness of breath who cannot lie flat (orthopnea) should be scanned:","Sitting up or semi-upright as tolerated",["Flat on the back","Prone","Head down"],"Adjust the exam to keep the patient safe and comfortable.","F"),
(C,"When working with a patient who has dementia, the sonographer should:","Use short, simple explanations, a calm voice and involve caregivers if available",["Rush the exam","Restrain the patient","Speak loudly and quickly"],"Patience reduces agitation.","F"),
(C,"For a patient who is hard of hearing, the sonographer should:","Face the patient, speak clearly and use written notes if needed",["Shout","Avoid speaking","Speak while facing away"],"Make sure the patient understands each step.","F"),
(C,"In a child, a good way to reduce fear during an echo is to:","Explain simply, let a parent stay, and use distraction such as videos",["Separate them from parents","Restrain without explanation","Hurry"],"A calm child gives better images.","F"),
(C,"A slide board or lift is used to:","Move patients safely from bed to stretcher without lifting them by hand",["Clean the probe","Measure weight","Hold the transducer"],"It reduces injury to patients and staff.","F"),
(C,"A patient with a continuous-flow LVAD may have:","No palpable pulse, so blood pressure is often measured with a Doppler probe as MAP",["A very strong pulse","High pulse pressure","Normal cuff readings always"],"Know how to recognize alarms and get help.","C"),
(C,"For patients with a pacemaker or ICD, a magnet placed over the device:","Can change how the device works, so it is used only under instruction",["Has no effect","Charges the battery","Is always required during echo"],"Ultrasound itself does not affect the device.","C"),
(C,"In a patient with chest tubes, drains and many IV lines, the sonographer should:","Check all lines before moving and avoid pulling or kinking them",["Remove tubes to get better images","Ignore the lines","Move the patient quickly"],"Ask nursing staff for help if needed.","F"),
# --- ICU and shock ---
(C,"The four main types of shock are:","Hypovolemic, cardiogenic, distributive and obstructive",["Mild, moderate, severe and fatal","Left, right, central and peripheral","Acute, chronic, early and late"],"Echo helps tell them apart.","F"),
(C,"Echo in hypovolemic shock typically shows:","A small, hyperdynamic LV and a small, collapsing IVC",["A dilated LV with low EF","A large pericardial effusion","A dilated RV"],"The heart is underfilled.","F"),
(C,"Echo in cardiogenic shock typically shows:","Poor LV (or RV) function, often with a dilated IVC",["A small hyperdynamic LV","Normal function","A small IVC"],"Causes include large MI and severe valve disease.","F"),
(C,"Obstructive shock can be caused by:","Tamponade, massive PE or tension pneumothorax",["Dehydration","Sepsis","Anaphylaxis only"],"Echo can detect tamponade and RV strain.","F"),
(C,"In distributive shock (such as sepsis), echo often shows:","A hyperdynamic LV with low systemic resistance",["A small effusion only","Severe MS","An LV thrombus"],"Later, septic cardiomyopathy may reduce function.","F"),
(C,"During CPR, a focused echo should be done:","During the pulse check, in under 10 seconds, without delaying compressions",["During compressions only","Instead of CPR","For several minutes at a time"],"It can detect tamponade or no cardiac motion.","F"),
(C,"Pulseless electrical activity with a large pericardial effusion suggests:","Tamponade, which may be treatable with pericardiocentesis",["Normal heart","Asystole","Aortic stenosis"],"Echo can identify reversible causes during arrest.","F"),
(C,"High PEEP on a ventilator can affect echo by:","Raising intrathoracic pressure, reducing venous return and dilating the IVC",["Making the IVC collapse more","Raising the EF","Having no effect"],"Interpret IVC size cautiously in ventilated patients.","C"),
# --- ECG and vitals ---
(C,"Atrial fibrillation with a ventricular rate over about 100 bpm is called:","AF with rapid ventricular response",["Sinus tachycardia","Atrial flutter","Heart block"],"Fast rates make echo measurements less accurate.","F"),
(C,"Ventricular bigeminy means:","Every other beat is a premature ventricular contraction",["Two P waves per QRS","Two normal beats then a pause","Atrial fibrillation"],"It can make Doppler and EF measurements variable.","F"),
(C,"Pathological Q waves on the ECG usually indicate:","A previous myocardial infarction",["Normal finding","Atrial enlargement","Low potassium"],"Look for matching wall motion abnormalities on echo.","F"),
(C,"High QRS voltages with ST–T changes on ECG suggest:","Left ventricular hypertrophy",["Pericardial effusion","Hypothyroidism","Amyloidosis"],"Echo confirms LV wall thickness and mass.","F"),
(C,"A normal corrected QT (QTc) is usually under about:","440 ms in men and 460 ms in women",["300 ms","600 ms","200 ms"],"Long QT increases arrhythmia risk.","C"),
(C,"Hypertensive emergency differs from hypertensive urgency because emergency involves:","Very high blood pressure with acute organ damage",["Slightly high blood pressure","No symptoms","Low blood pressure"],"Organ damage may include stroke, MI or aortic dissection.","F"),
(C,"Hypoglycemia is usually defined as a blood glucose below:","70 mg/dL (3.9 mmol/L)",["150 mg/dL","200 mg/dL","40 mmol/L"],"Give fast-acting sugar if the patient can swallow.","F"),
(C,"A pain score is commonly recorded on a scale of:","0 to 10",["1 to 3","0 to 100 only","A to F"],"Ask about pain before and after procedures.","F"),
(C,"Junctional rhythm on ECG shows:","Narrow QRS with absent or inverted P waves, usually at 40–60 bpm",["Wide QRS at 150 bpm","Sawtooth flutter waves","Irregular chaos"],"It comes from the AV junction.","C"),
# --- Labs ---
(C,"NT-proBNP and BNP levels can be lower than expected in:","Obese patients",["Kidney failure","Older age","Atrial fibrillation"],"Kidney failure and older age tend to raise levels.","C"),
(C,"High-sensitivity troponin is useful because it:","Detects very small amounts of heart muscle injury early",["Measures cholesterol","Measures kidney function","Detects infection"],"Rising values over hours point to acute injury.","F"),
(C,"Before TEE, a low platelet count is important because it:","Raises the risk of bleeding from the throat or esophagus",["Prevents infection","Improves images","Has no effect"],"The physician decides whether it is safe to proceed.","F"),
(C,"A high TSH with low thyroid hormone suggests:","Hypothyroidism, which can cause pericardial effusion and bradycardia",["Hyperthyroidism","Diabetes","Kidney failure"],"Thyroid disease affects heart rate and function.","C"),
(C,"Low magnesium is important in cardiac patients because it:","Raises the risk of arrhythmias such as torsades",["Lowers blood pressure only","Improves EF","Has no effect"],"Magnesium is given to treat torsades.","F"),
(C,"Hemoglobin A1c reflects:","Average blood sugar over about the past 3 months",["Today's blood sugar only","Cholesterol","Kidney function"],"It is used to diagnose and monitor diabetes.","F"),
# --- Documentation ---
(C,"If a sonographer needs to correct an error in a report or record, they should:","Follow the facility's amendment process, keeping the original visible",["Delete the original","Use correction fluid","Rewrite the whole chart"],"Records must show what was changed and when.","F"),
(C,"Abbreviations such as 'U' for units and 'QD' for daily are on 'do not use' lists because:","They are easily misread and can cause medication errors",["They are too long","They are only for children","They are always correct"],"Write the full words instead.","F"),
(C,"A verbal or telephone order should be:","Written down, read back and confirmed",["Remembered without writing","Ignored","Followed without confirming"],"Read-back reduces errors.","F"),
(C,"Protected health information (PHI) includes:","Name, date of birth, medical record number and images linked to the patient",["Only the diagnosis","Only the doctor's name","Only billing codes"],"PHI must be protected under HIPAA.","F"),
(C,"Leaving a patient alone on the exam table without arranging care could be considered:","Patient abandonment",["Good practice","Teamwork","Efficiency"],"Make sure someone takes over the patient's care.","F"),
# --- Ethics and law ---
(C,"The four basic principles of medical ethics are:","Autonomy, beneficence, non-maleficence and justice",["Speed, cost, size and color","Gain, depth, focus and frequency","Diagnosis, treatment, billing and follow-up"],"These guide decisions in patient care.","F"),
(C,"Respecting a patient's right to make their own decisions is called:","Autonomy",["Beneficence","Justice","Non-maleficence"],"Patients may refuse tests after being informed.","F"),
(C,"'Do no harm' is the principle of:","Non-maleficence",["Autonomy","Justice","Beneficence"],"Beneficence means doing good for the patient.","F"),
(C,"The four elements needed to prove negligence are:","Duty, breach of duty, causation and damages",["Speed, accuracy, cost and time","Consent, privacy, safety and billing","Diagnosis, imaging, reporting and storage"],"All four must be present.","C"),
(C,"Touching a patient without consent can be considered:","Battery",["Assault only","Good practice","Teamwork"],"Assault is the threat of harmful contact.","C"),
(C,"Malpractice refers to:","Professional negligence by a healthcare worker",["Any accident at work","Equipment failure only","A billing error"],"Following protocols and documenting carefully reduces risk.","F"),
(C,"The ARDMS code of ethics expects sonographers to:","Act honestly, protect patients and stay within their scope of practice",["Provide diagnoses to patients","Share images freely","Work outside their training"],"Violations can lead to loss of credentials.","F"),
(C,"Cultural competence in patient care means:","Respecting patients' beliefs and needs, such as requests for a same-gender sonographer when possible",["Treating everyone the same way without asking","Ignoring cultural needs","Refusing to scan certain patients"],"Respectful care improves trust and cooperation.","F"),
(C,"A patient asks to stop the exam halfway. The sonographer should:","Stop, respect the request, document it and inform the physician",["Continue anyway","Ignore the request","Restrain the patient"],"Patients can withdraw consent at any time.","F"),
# --- Safety and workflow ---
(C,"Ultrasound gel should be warmed (when possible) to:","Improve patient comfort",["Improve image resolution","Sterilize it","Change its acoustic properties"],"Do not overheat gel warmers.","F"),
(C,"Before the first patient each day, the ultrasound machine should be checked for:","Damaged cables, cracked probes and correct date and time",["Battery color only","Screen size","Nothing"],"Damaged probes can cause electrical injury.","F"),
(C,"Ergonomically, the ultrasound monitor should be placed:","At eye level, directly in front of the sonographer",["Far to the side","Above the head","On the floor"],"This reduces neck strain.","F"),
(C,"An exam ordered as 'urgent' or 'STAT' should be:","Performed as soon as possible according to the lab's priority system",["Done next week","Ignored","Done only after all routine exams"],"Communicate expected timing with the ordering team.","F"),
(C,"If the wrong patient was scanned, the sonographer should:","Stop, report the error, and correct the record according to policy",["Continue and say nothing","Delete images without reporting","Change the patient's name on the images"],"Honest reporting protects patients.","F"),
(C,"Keeping the room temperature comfortable and covering the patient with a sheet helps:","Patient comfort and privacy",["Image resolution","Doppler accuracy","Frame rate"],"Only expose the area needed for scanning.","F"),
(C,"If a patient vomits during an exam, the sonographer should first:","Turn the patient to the side to prevent choking and call for help if needed",["Leave the room","Continue scanning","Lay the patient flat on the back"],"Protect the airway.","F"),
]
